149	int Touch_Init(void)
150	{
151	    /* Bật clock GPIOB */
152	    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOBEN;
153	    
154	    /* Cấu hình PB8 (SCL) và PB9 (SDA): Output Open-Drain, Pull-up, High Speed */
155	    /* PB8: MODER bits 17:16 = 01 */
156	    /* PB9: MODER bits 19:18 = 01 */
157	    GPIOB->MODER &= ~((3UL << (8 * 2)) | (3UL << (9 * 2)));
158	    GPIOB->MODER |=  ((1UL << (8 * 2)) | (1UL << (9 * 2)));
159	    
160	    /* Open-drain: OTYPER bit 8 = 1, bit 9 = 1 */
161	    GPIOB->OTYPER |= (1UL << 8) | (1UL << 9);
162	    
163	    /* Pull-up: PUPDR bits 17:16 = 01, bits 19:18 = 01 */
164	    GPIOB->PUPDR &= ~((3UL << (8 * 2)) | (3UL << (9 * 2)));
165	    GPIOB->PUPDR |=  ((1UL << (8 * 2)) | (1UL << (9 * 2)));
166	    
167	    /* Very High speed: OSPEEDR bits 17:16 = 11, bits 19:18 = 11 */
168	    GPIOB->OSPEEDR |= ((3UL << (8 * 2)) | (3UL << (9 * 2)));
169	    
170	    /* 9 xung unlock bus I2C */
171	    sda_high();
172	    for (int i = 0; i < 9; i++) {
173	        scl_low();
174	        i2c_delay();
175	        scl_high();
176	        i2c_delay();
177	    }
178	    i2c_stop();
179	    
180	    /* Quét địa chỉ IC cảm ứng */
181	    i2c_start();
182	    if (i2c_write_byte(TS_ADDR_1) == 0) {
183	        g_ts_addr = TS_ADDR_1;
184	        i2c_stop();
185	        return 0;
186	    }
187	    i2c_stop();
188	    
189	    i2c_start();
190	    if (i2c_write_byte(TS_ADDR_2) == 0) {
191	        g_ts_addr = TS_ADDR_2;
192	        i2c_stop();
193	        return 0;
194	    }
195	    i2c_stop();
196	    
197	    /* Mặc định dùng TS_ADDR_1 */
198	    g_ts_addr = TS_ADDR_1;
199	    return 0;
200	}
201	
202	int Touch_Read(uint16_t *x, uint16_t *y)
203	{
204	    uint8_t data[5];
205	    /* Đọc 5 byte từ thanh ghi 0x02 (TD_STATUS) đến 0x06 */
206	    if (i2c_read_regs(g_ts_addr, 0x02, data, 5) != 0) {
207	        return 0;
208	    }
209	    
210	    uint8_t touches = data[0] & 0x0F;
211	    if (touches == 0 || touches > 2) {
212	        return 0;
213	    }
214	    
215	    uint16_t raw_x = ((uint16_t)(data[1] & 0x0F) << 8) | data[2];
216	    uint16_t raw_y = ((uint16_t)(data[3] & 0x0F) << 8) | data[4];
217	    
218	    /* Trên màn hình STM32F469I-DISCO OTM8009A ở chế độ Landscape (800x480):
219	     * raw_y là trục dài (0..799)
220	     * raw_x là trục ngắn (0..479)
221	     */
222	    if (x != 0) {
223	        *x = raw_y;
224	    }
225	    if (y != 0) {
226	        *y = raw_x;
227	    }
228	    return 1;
229	}

  1	/**
  2	 * @file main.c
  3	 * @brief Chương trình chính STM32F469I-DISCO với 6 tác vụ trên nhân RTOS tiền định
  4	 *        chuyển đổi từ tham-khao/main-freertos.c:
  5	 *        1. vTaskLED1
  6	 *        2. vTaskLED2
  7	 *        3. vTaskButton (quét nút USER PA0)
  8	 *        4. vTaskLED3 (chờ hàng đợi từ nút bấm)
  9	 *        5. vTaskMonitor (nhịp tim LED4 PK3)
 10	 *        6. vTaskLCD (quản lý LCD DSI OTM8009A, cảm ứng FT6206)
 11	 */
 12	
 13	#include <stdint.h>
 14	#include <stdbool.h>
 15	#include "stm32f469xx.h"
 16	#include "stm32f4xx_hal.h"
 17	#include "rtos/rtos_types.h"
 18	#include "ui.h"
 19	#include "touch.h"
 20	
 21	/* Định nghĩa chân LED trên STM32F469I-DISCO (Active LOW) */
 22	/* LED1: PG6, LED2: PD4, LED3: PD5, LED4: PK3 */
 23	#define LED1_PIN              (6UL)
 24	#define LED2_PIN              (4UL)
 25	#define LED3_PIN              (5UL)
 26	#define LED4_PIN              (3UL)
 27	
 28	/* Định nghĩa chân nút bấm USER (Active HIGH) - WAKEUP: PA0 */
 29	#define BUTTON_PIN            (0UL)
 30	
 31	/* Dung lượng hàng đợi sự kiện */
 32	#define QUEUE_CAPACITY        4U
 33	
 34	/* Hàng đợi truyền tín hiệu sự kiện từ nút bấm PA0 sang tác vụ LED3 và LCD */
 35	static uint32_t button_queue_storage[QUEUE_CAPACITY];
 36	static rtos_queue_t xButtonQueue;
 37	
 38	static uint32_t ui_queue_storage[QUEUE_CAPACITY];
 39	static rtos_queue_t xUIQueue;
 40	
 41	/* Vùng nhớ tĩnh TCB và Stack cho 6 tác vụ */
 42	static rtos_tcb_t tcb_led1;
 43	static uint32_t stack_led1[RTOS_DEFAULT_STACK_WORDS];
 44	
 45	static rtos_tcb_t tcb_led2;
 46	static uint32_t stack_led2[RTOS_DEFAULT_STACK_WORDS];
 47	
 48	static rtos_tcb_t tcb_button;
 49	static uint32_t stack_button[RTOS_DEFAULT_STACK_WORDS];
 50	
 51	static rtos_tcb_t tcb_led3;
 52	static uint32_t stack_led3[RTOS_DEFAULT_STACK_WORDS];
 53	
 54	static rtos_tcb_t tcb_monitor;
 55	static uint32_t stack_monitor[RTOS_DEFAULT_STACK_WORDS];
 56	
 57	static rtos_tcb_t tcb_lcd;
 58	static uint32_t stack_lcd[1024U]; /* Stack mở rộng cho tác vụ LCD và Touch */
 59	
 60	extern uint32_t SystemCoreClock;
 61	
 62	/**
 63	 * @brief Cấu hình hệ thống xung nhịp lên 180 MHz từ HSE (tương thích cấu hình tham khảo FreeRTOS).
 64	 */
 65	static void prvSetupClock180MHz(void)
 66	{
 67	    /* 1. Bật HSE */
 68	    RCC->CR |= RCC_CR_HSEON;
 69	    for (volatile uint32_t timeout = 0; timeout < 100000; timeout++) {
 70	        if (RCC->CR & RCC_CR_HSERDY) {
 71	            break;
 72	        }
 73	    }
 74	
 75	    /* 2. Bật clock PWR Controller và đặt chế độ Scale 1 */
 76	    RCC->APB1ENR |= RCC_APB1ENR_PWREN;
 77	    (void)RCC->APB1ENR;
 78	    PWR->CR |= PWR_CR_VOS;
 79	
 80	    /* 3. Đặt bộ chia bus APB1 = /4, APB2 = /2 */
 81	    RCC->CFGR |= RCC_CFGR_PPRE1_DIV4 | RCC_CFGR_PPRE2_DIV2;
 82	
 83	    /* 4. Cấu hình Main PLL: HSE / 8 * 360 / 2 = 180 MHz */
 84	    RCC->PLLCFGR = (8UL << RCC_PLLCFGR_PLLM_Pos)
 85	                 | (360UL << RCC_PLLCFGR_PLLN_Pos)
 86	                 | (0UL << RCC_PLLCFGR_PLLP_Pos)
 87	                 | RCC_PLLCFGR_PLLSRC_HSE
 88	                 | (7UL << RCC_PLLCFGR_PLLQ_Pos)
 89	                 | (6UL << RCC_PLLCFGR_PLLR_Pos);
 90	
 91	    /* 5. Bật PLL chính và chờ sẵn sàng */
 92	    RCC->CR |= RCC_CR_PLLON;
 93	    while (!(RCC->CR & RCC_CR_PLLRDY));
 94	
 95	    /* 6. Kích hoạt chế độ Over-Drive */
 96	    PWR->CR |= PWR_CR_ODEN;
 97	    while (!(PWR->CSR & PWR_CSR_ODRDY));
 98	    PWR->CR |= PWR_CR_ODSWEN;
 99	    while (!(PWR->CSR & PWR_CSR_ODSWRDY));
100	
101	    /* 7. Cấu hình Flash 5 Wait States, bật Prefetch, IC và DC */
102	    FLASH->ACR = FLASH_ACR_LATENCY_5WS | FLASH_ACR_PRFTEN | FLASH_ACR_ICEN | FLASH_ACR_DCEN;
103	
104	    /* 8. Chuyển nguồn SYSCLK sang PLL và chờ hoàn tất */
105	    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;
106	    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL);
107	
108	    /* 9. Cập nhật biến SystemCoreClock cho RTOS và ngoại vi */
109	    SystemCoreClock = 180000000UL;
110	}
