112	/**
113	 * @brief Cung cấp hàm thời gian HAL dựa trên RTOS tick count.
114	 */
115	uint32_t HAL_GetTick(void)
116	{
117	    return rtos_get_tick_count();
118	}
119	
120	/**

121	 * @brief Hàm trễ phần cứng thích ứng với RTOS delay.
122	 */
123	void HAL_Delay(uint32_t Delay)
124	{
125	    if (Delay == 0) {
126	        return;
127	    }
128	    if (rtos_get_tick_count() > 0) {
129	        rtos_delay_ms(Delay);
130	    } else {
131	        /* Vòng lặp chờ thô khi scheduler chưa khởi chạy */
132	        for (volatile uint32_t i = 0; i < Delay * 40000; i++) {
133	            __asm__("nop");
134	        }
135	    }
136	}
137	
138	/**
139	 * @brief Khởi tạo ngoại vi phần cứng: 4 LED và nút WAKEUP PA0.
140	 */
141	static void prvSetupHardware(void)
142	{
143	    /* Cấu hình xung nhịp hệ thống lên 180 MHz từ HSE */
144	    prvSetupClock180MHz();
145	
146	    /* Bật clock AHB1 cho GPIOA, GPIOD, GPIOG, GPIOK */
147	    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN | RCC_AHB1ENR_GPIODEN | RCC_AHB1ENR_GPIOGEN | RCC_AHB1ENR_GPIOKEN;
148	
149	    /* Cấu hình PA0 (Nút WAKEUP): Chế độ Input (00), Pull-down (10) */
150	    GPIOA->MODER &= ~(3UL << (BUTTON_PIN * 2));
151	    GPIOA->PUPDR &= ~(3UL << (BUTTON_PIN * 2));
152	    GPIOA->PUPDR |= (2UL << (BUTTON_PIN * 2));
153	
154	    /* Cấu hình PG6 (LED1): Chế độ Output (01), tắt ban đầu (LED tích cực mức thấp) */
155	    GPIOG->MODER &= ~(3UL << (LED1_PIN * 2));
156	    GPIOG->MODER |= (1UL << (LED1_PIN * 2));
157	    GPIOG->BSRR = (1UL << LED1_PIN);
158	
159	    /* Cấu hình PD4 (LED2) & PD5 (LED3): Chế độ Output (01), tắt ban đầu */
160	    GPIOD->MODER &= ~((3UL << (LED2_PIN * 2)) | (3UL << (LED3_PIN * 2)));
161	    GPIOD->MODER |= ((1UL << (LED2_PIN * 2)) | (1UL << (LED3_PIN * 2)));
162	    GPIOD->BSRR = (1UL << LED2_PIN) | (1UL << LED3_PIN);
163	
164	    /* Cấu hình PK3 (LED4): Chế độ Output (01), tắt ban đầu */
165	    GPIOK->MODER &= ~(3UL << (LED4_PIN * 2));
166	    GPIOK->MODER |= (1UL << (LED4_PIN * 2));
167	    GPIOK->BSRR = (1UL << LED4_PIN);
168	}
169	
170	/**
171	 * @brief Task 1: Nháy LED1 (PG6) theo chu kỳ.
172	 */
173	static void vTaskLED1(void *arg)
174	{
175	    (void)arg;
176	    for (;;) {
177	        GPIOG->BSRR = (1UL << (LED1_PIN + 16)); /* Bật LED1 (mức thấp) */
178	        rtos_delay_ms(500U);
179	        GPIOG->BSRR = (1UL << LED1_PIN);        /* Tắt LED1 (mức cao) */
180	        rtos_delay_ms(500U);
181	    }
182	}
183	
184	/**
185	 * @brief Task 2: Nháy LED2 (PD4) theo chu kỳ.
186	 */
187	static void vTaskLED2(void *arg)
188	{
189	    (void)arg;
190	    for (;;) {
191	        GPIOD->BSRR = (1UL << (LED2_PIN + 16)); /* Bật LED2 */
192	        rtos_delay_ms(200U);
193	        GPIOD->BSRR = (1UL << LED2_PIN);        /* Tắt LED2 */
194	        rtos_delay_ms(200U);
195	    }
196	}
197	
198	/**
199	 * @brief Task 3: Đọc nút bấm PA0 (quét định kỳ, chống rung) và gửi thông điệp vào Queues.
200	 */
201	static void vTaskButton(void *arg)
202	{
203	    (void)arg;
204	    uint8_t prev_state = 0;
205	
206	    for (;;) {
207	        uint8_t state = (GPIOA->IDR & (1UL << BUTTON_PIN)) ? 1U : 0U;
208	        if (state && !prev_state) {
209	            uint32_t msg = 1U;
210	            rtos_queue_send(&xButtonQueue, &msg, 0U);
211	            rtos_queue_send(&xUIQueue, &msg, 0U);
212	        }
213	        prev_state = state;
214	        rtos_delay_ms(30U);
215	    }
216	}
217	
218	/**
219	 * @brief Task 4: Chờ tín hiệu từ Queue để đảo trạng thái LED3 (PD5).
220	 */
221	static void vTaskLED3(void *arg)
222	{
223	    (void)arg;
224	    uint32_t rx_msg = 0;
225	    uint8_t led_state = 0;
226	
227	    for (;;) {
228	        if (rtos_queue_receive(&xButtonQueue, &rx_msg, 1000U) == RTOS_OK) {
229	            led_state = !led_state;
230	            if (led_state) {
231	                GPIOD->BSRR = (1UL << (LED3_PIN + 16)); /* Bật LED3 */
232	            } else {
233	                GPIOD->BSRR = (1UL << LED3_PIN);        /* Tắt LED3 */
234	            }
235	        }
236	    }
237	}
238	
239	/**
240	 * @brief Task 5: Giám sát hệ thống qua LED4 (PK3) - nhịp tim định kỳ.

241	 */
242	static void vTaskMonitor(void *arg)
243	{
244	    (void)arg;
245	    for (;;) {
246	        GPIOK->BSRR = (1UL << (LED4_PIN + 16)); /* Bật LED4 */
247	        rtos_delay_ms(100U);
248	        GPIOK->BSRR = (1UL << LED4_PIN);        /* Tắt LED4 */
249	        rtos_delay_ms(1900U);
250	    }
251	}
252	
253	/**
254	 * @brief Task 6: Quản lý hiển thị LCD DSI OTM8009A và quét cảm ứng điện dung FT6206.
255	 */
256	static void vTaskLCD(void *arg)
257	{
258	    (void)arg;
259	    uint32_t rx_msg = 0;
260	
261	    /* Khởi tạo SDRAM và màn hình LCD DSI */
262	    UI_Init();
263	
264	    /* Khởi tạo cảm ứng điện dung qua I2C */
265	    Touch_Init();
266	
267	    uint8_t touch_was_pressed = 0;
268	
269	    for (;;) {
270	        /* Chờ tín hiệu từ nút bấm vật lý PA0 (timeout để kết hợp quét cảm ứng) */
271	        if (rtos_queue_receive(&xUIQueue, &rx_msg, 40U) == RTOS_OK) {
272	            UI_ToggleScreen();
273	        }
274	
275	        /* Quét điểm chạm trên màn hình cảm ứng */
276	        uint16_t tx = 0;
277	        uint16_t ty = 0;
278	        if (Touch_Read(&tx, &ty)) {
279	            if (!touch_was_pressed) {
280	                UI_HandleTouch(tx, ty);
281	                touch_was_pressed = 1U;
282	            }
283	        } else {
284	            touch_was_pressed = 0U;
285	        }
286	    }
287	}
