289	/**
290	 * @brief Điểm khởi nhập chính của ứng dụng firmware.
291	 */
292	int main(void)
293	{
294	    /* 1. Thiết lập phần cứng (GPIO LED và nút bấm) */
295	    prvSetupHardware();
296	
297	    /* 2. Khởi tạo lõi RTOS */
298	    rtos_init();
299	
300	    /* 3. Khởi tạo hàng đợi tĩnh IPC cho sự kiện nút bấm */
301	    rtos_queue_init(
302	        &xButtonQueue,
303	        button_queue_storage,
304	        sizeof(uint32_t),
305	        QUEUE_CAPACITY
306	    );
307	
308	    rtos_queue_init(
309	        &xUIQueue,
310	        ui_queue_storage,
311	        sizeof(uint32_t),
312	        QUEUE_CAPACITY
313	    );
314	
315	    /* 4. Tạo 6 tác vụ với các mức ưu tiên riêng biệt (0 cao nhất, 31 idle).
316	     * Nhân O(1) quy định mỗi mức ưu tiên chỉ gắn với 1 tác vụ:
317	     * - Button (1U): ưu tiên cao nhất để quét nút bấm kịp thời
318	     * - LCD (2U): ưu tiên cao cho tương tác giao diện và cảm ứng
319	     * - LED3 (3U): phản hồi sự kiện từ hàng đợi nút bấm
320	     * - LED2 (4U): tác vụ nháy chu kỳ 400 ms
321	     * - LED1 (5U): tác vụ nháy chu kỳ 1000 ms
322	     * - Monitor (6U): tác vụ giám sát nhịp tim hệ thống
