+    /* 4. Cấu hình Main PLL: HSE / 8 * 360 / 2 = 180 MHz */
+    RCC->PLLCFGR = (8UL << RCC_PLLCFGR_PLLM_Pos)
+                 | (360UL << RCC_PLLCFGR_PLLN_Pos)
+                 | (0UL << RCC_PLLCFGR_PLLP_Pos)
+                 | RCC_PLLCFGR_PLLSRC_HSE
+                 | (7UL << RCC_PLLCFGR_PLLQ_Pos)
